"""Concise native hover definitions for navigation, section headers and form labels."""
import json
import streamlit.components.v1 as components
DEFINITIONS={'Retail Intelligence': 'Coordinates vendor approval, item setup and buying requests so teams know what must happen next.', 'Supporting tools': 'Standalone workbenches that validate the source data used by orchestration.', 'Launch decision': 'Whether this launch can proceed and the prerequisites still blocking it.', 'Actions': 'Recommended corrections and the people accountable for completing them.', 'Evidence': 'What each agent checked and the source records supporting its findings.', 'Review & audit': 'Human decisions, evidence history and local administration.', 'Vendor readiness': 'Vendor data and approval evidence needed before purchasing.', 'Item / Catalog readiness': 'Product data and item-setup evidence needed before ordering.', 'PO request readiness': 'Order checks combined with vendor and item prerequisites.', 'How each agent supports this decision': 'How source checks combine into a buying recommendation.', 'What prevents this launch?': 'Open findings grouped by source, with their share of all findings.', 'Top Recommended Actions': 'Ranked issue groups showing the next correction, affected SKUs and accountable team.', 'Next action': 'The highest-ranked unresolved correction for the selected evidence.', 'Did our corrections help?': 'Changes in findings since the previous validation of this launch.', 'Launch readiness & control coverage': 'Which requested controls were evaluated and which remain unavailable.', 'Commercial commitment and affected value': 'Measured cost times quantity, separated by currency and affected PO line.', 'Upload or replace files': 'Select the vendor, item and PO files for one business cycle.', 'Launch setup · name, date, channel & scope': 'Define the launch and records covered by its decision.', 'Use results published by standalone agents': 'Verify three selected source publications against the uploaded originals.', 'Release subsets · eligible, blocked and review': 'Separate PO lines by readiness without authorizing a partial release.', 'Commercial impact · value and missing inputs': 'Measured commitment and the inputs still needed to value it.', 'Correction progress · previous versus current': 'Compare resolved, new, reopened and remaining findings.', 'What can proceed while approvals are pending?': 'Distinguishes preparing a draft request from creating an executable PO.', 'Assign all filtered corrections together': 'Assign one owner and deadline to every correction matching the current filters.', 'Assign or return to a team': 'Hand an unresolved correction to its next team and record the reason.', 'Action history & export': 'Recorded assignment changes, handoffs and evidence-based resolutions.', 'Maintain channel requirement versions': 'Administration: save reusable catalog requirements for a channel.', 'Local backups & recovery': 'Create or verify a local evidence backup without replacing live data.', 'Record your decision': 'Record a human review after the required validation gates are satisfied.', 'Evidence provenance': 'The source execution, policy version and origin behind this evidence.', 'Margin & revenue scenarios': 'Optional estimates based on an explicit sell-through assumption.', 'Details & downloads': 'Download the selected decision and its supporting evidence.', 'Rank recommendations by': 'Choose how severity, deadlines or comparable commitment determine ranking.', 'Receiving team': 'The team accountable for the next correction, including returned requests.', 'Named action owner': 'The person responsible for completing this correction.', 'Calendar deadline': 'The date by which the assigned correction should be completed.', 'Work status': 'Progress reported by the owner; only revalidation resolves a finding.', 'Prerequisite actions': 'Corrections that must finish before this action can proceed.', 'Escalation contact': 'The person to involve if the correction stalls or becomes overdue.', 'Escalation note / next step': 'The local escalation request and the action needed next.', 'Assignment recorded by': 'The person recording this ownership change.', 'Assignment reason': 'Why responsibility or the deadline is changing.', 'Deadline filter': 'Show corrections in the selected due-date window.', 'Owner filter': 'Show corrections assigned to one owner or still unassigned.', 'Correction source': 'Filter findings by the engine or dependency check that raised them.', 'Business cycle name': 'The business batch that groups related launches and validations.', 'Launch name': 'The specific launch being reviewed within the business cycle.', 'Planned launch date': 'The target date used to assess timing and action deadlines.', 'Launch channels': 'The selling channels covered by this launch.', 'Launch locations': 'The business locations described by this launch.', 'SKU scope': 'Limit evaluation to these SKU IDs; blank includes all supplied SKUs.', 'PO location scope': 'Limit evaluation to these PO locations; blank includes all.', 'Channel requirement version': 'The saved set of channel attributes applied at validation.', 'Mandatory catalog fields for these channels': 'Product attributes that must be present for the selected channels.', 'Policy name': 'The business name of this reusable channel requirement set.', 'Policy version': 'A distinct immutable revision of the channel requirements.', 'Required catalog columns': 'Product fields required by this version of the channel policy.', 'Policy source or internal rationale': 'The business reason or reference supporting these requirements.', 'Policy author': 'The person accountable for this policy version.', 'Onboarding Intelligence': 'Vendor and item inputs needed to begin the buying workflow.', 'Catalog Intelligence': 'Checks product content and required item attributes.', 'PO / Buying Intelligence': 'Checks purchase-order data and buying prerequisites.', 'Can we buy from this vendor?': 'Vendor source checks plus explicit Finance approval evidence.', 'Is the item ready for an order?': 'Catalog quality plus evidence that item setup is active.', 'Can this purchase request proceed?': 'PO rules combined with linked vendor, category, gender and approval checks.'}

DEFINITIONS.update({
 'Accountable team':'Filter the recommendations, detailed queue and assignments by current receiving team.',
 'Track a buying request before item setup':'Track draft purchase requests and ownership before source records are ready for validation.',
 'Request handoff history':'Who handed this draft request to whom, when, and why.',
 'Connection diagnostics':'Freshness and availability of the connected agent publications.',
 'Inspect or export the release subsets':'Select the PO-line population to inspect or download.',
 'Which file goes where? / Download test files':'Upload requirements and sample datasets for validating the workflow.',
 'Ask about your data':'Look up saved findings, counts and source evidence in plain language.',
 'Revalidation required':'Saved evidence must be checked against the current prerequisites before approval.',
 'Hold':'Unresolved critical requirements prevent this launch proceeding.',
 'Approved':'A reviewer approved this evidence version; no ERP transaction has been sent.',
 'Ready for human review':'Configured checks passed and a named reviewer must decide.',
 'Review warnings':'Noncritical findings need explicit human review.'})

def render_header_definitions():
    DEFINITIONS.update({'Agent explanations':'Short explanations of the three specialist contributions to this decision.','Supporting evidence & downloads':'Expand only when you need detailed records, findings, history or source files.','Priority corrections · Excel download':'Grouped next actions for the selected team, with a full Excel export.'})
    DEFINITIONS.update({'Supporting controls and commercial evidence':'Additional coverage checks and measured values supporting the three agent assessments.','Batch receiving team':'The team receiving all corrections matching the filters; choose Keep current teams to preserve routing.'})
    definitions=json.dumps(DEFINITIONS).replace('</',r'<\/')
    components.html("""<script>
    const definitions="""+definitions+""";
    const doc=window.parent.document;
    function apply(){
      doc.querySelectorAll('h1,h2,h3,h4,[role="tab"],summary p,[data-testid="stWidgetLabel"] p,p > strong').forEach(el=>{
        const label=el.textContent.trim();
        let text=definitions[label];
        if(!text && /^(Catalog Operations|Buying Operations|Vendor Operations|Finance|Launch Operations) · /.test(label)) text='Recommended issue groups currently assigned to this team; the number is the group count.';
        if(!text && label.includes('Excel download')) text='Inspect and export these records with their evidence context.';
        if(!text && / · (Hold|Approved|Review warnings|Revalidation required)$/.test(label)) text='Current decision for this launch and evidence version.';
        if(text && el.title!==text){el.title=text;el.setAttribute('aria-description',text);}
      });
    }
    apply();
    if(window.parent.retailDefinitionObserver) window.parent.retailDefinitionObserver.disconnect();
    window.parent.retailDefinitionObserver=new MutationObserver(apply);
    window.parent.retailDefinitionObserver.observe(doc.body,{childList:true,subtree:true});
    </script>""",height=0)
